//! Every module fixture generated by rok-sqlc, compiled together.
//!
//! `src/db/` is written by the module fixture harness
//! (`tests/module_fixtures.rs` in rok-sqlc) and is not checked in. The lints
//! below are the generated-code quality bar (ADR 0013), the same as the
//! fixture crate's (`tests/fixture-app/src/lib.rs`).

#![deny(missing_docs, warnings)]
// The selected pedantic lints. They warn, so `deny(warnings)` and
// `cargo clippy -- -D warnings` turn any hit into an error.
#![warn(
    clippy::default_trait_access,
    clippy::doc_markdown,
    clippy::explicit_iter_loop,
    clippy::implicit_clone,
    clippy::items_after_statements,
    clippy::manual_let_else,
    clippy::match_same_arms,
    clippy::missing_panics_doc,
    clippy::must_use_candidate,
    clippy::needless_pass_by_value,
    clippy::redundant_closure_for_method_calls,
    clippy::ref_option,
    clippy::return_self_not_must_use,
    clippy::semicolon_if_nothing_returned,
    clippy::single_match_else,
    clippy::trivially_copy_pass_by_ref,
    clippy::uninlined_format_args,
    clippy::unnecessary_wraps
)]

pub mod db;
